use vstd::prelude::*;

verus! {

fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
    requires
        // (Redundant for Vec, but stated per problem)
        c.len() >= 0,
    ensures
        result.len() == c.len() + 1,
        result[0] == 0.0,
        // Shift: for every i with 1 <= i < c.len(), result[i+1] == c[i]
        forall|i: int| 1 <= i && i < c.len() ==> result[(i + 1) as int] == c[i],
{
    let n = c.len();
    let mut result: Vec<f64> = Vec::new();

    result.push(0.0);

    let mut i: usize = 1;
    while i < n
        invariant
            n == c.len(),
            result.len() == i + 1,
            result[0] == 0.0,
            forall|k: int| 1 <= k && k < i ==> result[(k + 1) as int] == c[k],
        decreases n - i,
    {
        // i < n implies i is an in-bounds index for c
        result.push(c[i]);
        i = i + 1;
    }

    // If n <= 1, loop doesn't run; specs are still satisfied (forall range empty)
    result
}

} // verus!

